import {mountServiceCheck} from './service-check.js';
import {applyAccessLegs,annotateCrowding} from './journey-enrichment.js';
import {boardingCrowd,nextDeparture} from './crowding.js';
import {validWeekdays,scheduledRoutines} from './routines.js';
import {planJourney,places,scenarios,formatTime,lines,metadata,affectedPairs} from './engine.js';
import {network} from './data/network.js';
import {validatePosition,gpsError,nearestStations} from './location.js';
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const defaults={origin:'tampines',destination:'raffles',departure:'07:40',deadline:'08:45',scenario:'normal',priority:'balanced',walkBreak:10,comfort:false,threshold:10,large:false};
const stateKeys=Object.keys(defaults);let state={...defaults},routines=[],activeRoutineId='';
try{
 const saved=JSON.parse(localStorage.getItem('margin-routine')||'null'),collection=JSON.parse(localStorage.getItem('margin-routines')||'null');
 if(Array.isArray(collection?.items)&&collection.items.length){routines=collection.items;activeRoutineId=collection.activeId||routines[0].id;const active=routines.find(item=>item.id===activeRoutineId)||routines[0];state={...state,...active.state};activeRoutineId=active.id;}
 else {state={...state,...saved};activeRoutineId='routine-1';routines=[{id:activeRoutineId,name:'Work commute',enabled:true,weekdays:[1,2,3,4,5],state:{...state}}];}
 planJourney(state);
}catch{state={...defaults};activeRoutineId='routine-1';routines=[{id:activeRoutineId,name:'Work commute',enabled:true,weekdays:[1,2,3,4,5],state:{...state}}];}
let plan,selected,zoom=1,stepIndex=0,toastTimer,gpsFix=null,gpsCandidate=null,gpsRequest=0,pickerField='origin',checkedMode=null;
let addresses={origin:null,destination:null},accessLegs={};const modal=$('#modal');
let crowdRequest=0;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{const active=routines.find(item=>item.id===activeRoutineId);if(active)active.state=Object.fromEntries(stateKeys.map(key=>[key,state[key]]));localStorage.setItem('margin-routine',JSON.stringify(state));localStorage.setItem('margin-routines',JSON.stringify({activeId:activeRoutineId,items:routines}));}catch{toast('Storage unavailable. Your routines will last for this session.');}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.add('hidden'),3500);}
function showModal(title,html,eyebrow='A LITTLE MORE CONTEXT'){ $('#modal-content').innerHTML=`<h2 id="dialog-title">${title}</h2>${html}`;$('#modal-eyebrow').textContent=eyebrow;if(!modal.open)modal.showModal();}
function currentRoute(){return plan.routes.find(r=>r.id===selected)||plan.best;}
function crowdText(route){const official=route.crowdObservations?.filter(item=>['live','forecast'].includes(item.source));return official?.length?official.map(item=>`${item.stationName}: ${item.label}`).join(' · '):`${{low:'Room to breathe',medium:'Some standing',high:'Likely crowded'}[route.crowd]} (demo)`;}
function crowdClass(route){const levels=route.crowdObservations?.filter(item=>['live','forecast'].includes(item.source)).map(item=>item.level);return levels?.includes('High')?'high':levels?.includes('Moderate')?'medium':levels?.includes('Low')?'low':route.crowd;}
function fillForm(){for(const key of ['origin','destination','deadline','departure','threshold','priority','walkBreak'])$('#'+key).value=state[key];$('#comfort').checked=state.comfort;$('#large-text').checked=state.large;const active=routines.find(item=>item.id===activeRoutineId);if(active){$('#routine-name').value=active.name;$('#routine-enabled').checked=active.enabled;$$('[data-weekday]').forEach(box=>box.checked=active.weekdays.includes(Number(box.dataset.weekday)));}document.body.classList.toggle('large-text',state.large);renderRoutineList();}
function renderRoutineList(){const host=$('#routine-list');if(!host)return;const days=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];host.innerHTML=routines.map(item=>`<button type="button" class="routine-card ${item.id===activeRoutineId?'active':''}" data-routine-id="${escape(item.id)}"><span><strong>${escape(item.name)}</strong><small>${escape(places[item.state.origin]?.name||item.state.origin)} → ${escape(places[item.state.destination]?.name||item.state.destination)} · ${item.state.departure} · ${item.weekdays.map(day=>days[day-1]).join(', ')||'No days'}</small></span><span class="routine-state">${item.enabled?'ON':'OFF'}</span></button>`).join('');$('#delete-routine').disabled=routines.length===1;}
function render(reset=true,override=null,skipCrowd=false){plan=override||applyAccessLegs(planJourney({...state,originLocation:gpsFix}),{...accessLegs,originStationName:places[state.origin].name,destinationLabel:addresses.destination?.label||places[state.destination].name});if(reset)selected=plan.best.id;const route=currentRoute();const recommended=plan.best;$('#scenario-label').textContent=checkedMode?(checkedMode.source==='live'?'OFFICIAL CHECK':'CHECKED DEMO'):'REPLAY';$('#decision-title').textContent=checkedMode?checkedMode.headline:recommended.buffer<0?'Let’s rethink your departure.':recommended.id==='usual'?'Your usual way looks good.':`Take ${recommended.lines.join(' → ')} today.`;$('#decision-copy').textContent=checkedMode?`This checked itinerary now drives the map and walkthrough. ${plan.accessVerified?'Its first and last walking legs use verified pedestrian routing.':'Station access is still an estimate.'}`:recommended.buffer<0?`The best estimated arrival misses ${state.deadline}. Leave by ${formatTime(plan.latestLeave)} if possible.`:plan.usual.delay?`The replay adds ${plan.usual.delay} minutes to your usual route. ${recommended.id==='usual'?'It still gives you enough time.':'This alternative avoids the affected segment.'}`:state.scenario==='normal'?'A plan for your everyday journey, shaped around your routine. Official crowd readings are shown when they apply; other conditions are labelled demo estimates.':'Your selected journey is not affected by the EWL replay disruption. Travel times remain estimates.';$('#route-count').textContent=`${plan.routes.length} route${plan.routes.length===1?'':'s'}`;
 $('#buffer').textContent=Math.abs(recommended.buffer);$('#buffer-unit').textContent=recommended.buffer<0?'min after your deadline':'min to breathe';$('#buffer-ring span').textContent=recommended.buffer<0?'!':'✓';$('#arrival-summary').textContent=`Arrive ${formatTime(plan.start+recommended.min)}–${formatTime(recommended.arrival)}`;$('#quiet-copy').textContent=plan.interrupted?'This change crosses your alert threshold. A heads-up is useful.':`Your ${plan.usual.buffer}-minute buffer is safe. No notification needed.`;
 $('#route-list').innerHTML=[...plan.routes].sort((a,b)=>(a.id===recommended.id?-1:b.id===recommended.id?1:0)).map(r=>`<button class="route-card ${r.id===selected?'selected':''}" data-route="${r.id}" aria-pressed="${r.id===selected}"><div class="route-top"><span class="route-name"><span class="radio"></span>${r.name}</span><span class="route-duration">${r.min}–${r.max} <small>min</small></span></div><div class="route-chain"><span class="walk">Walk</span><span>›</span>${r.lines.map(l=>l==='walk'?'<span class="walk">Walk</span>':`<span class="line-badge ${l.toLowerCase()}">${l}</span>`).join('<span>›</span>')}<span>›</span><span class="walk">Walk</span>${r.id===recommended.id?'<span class="recommend-tag">BEST FOR YOU</span>':''}</div><div class="route-meta"><span class="crowd"><span class="crowd-bars ${crowdClass(r)}"><i></i><i></i><i></i></span>${crowdText(r)}</span><span class="${r.delay?'delay-tag':''}">${r.delay?`+${r.delay} min delay`:`${r.walk} min walking`} · ${formatTime(r.arrival)}</span></div></button>`).join('');
 $('#network-title').textContent=checkedMode?'Checked route active':plan.usual.delay?'Your usual route is affected':plan.event.delay?'EWL event · outside your route':'No disruption in this replay';$('#network-copy').textContent=checkedMode?'Map and steps use the checked alternative':plan.usual.delay?`${state.scenario==='planned'?'Planned works':'Replay signal fault'} · +${plan.event.delay} min`:'Replay conditions · no major delays';$('#weather-title').textContent=plan.event.rain?'A little rain ahead':'A brighter start';$('#weather-copy').textContent=plan.event.rain?'Replay weather · bring an umbrella':'Replay weather · dry walking legs';$('#leave-label').textContent=`LEAVE AT ${state.departure}`;$('#step-preview').innerHTML=route.steps.slice(0,3).map((s,i)=>stepHtml(s,i)).join('');drawMap();renderMobileSummary();renderEveryday();mountServiceCheck({state,plan,places,onActivate:activateCheckedJourney});if(!skipCrowd)refreshMainCrowding(plan);}
async function refreshMainCrowding(basePlan){
 const request=++crowdRequest,lines=[...new Set(basePlan.routes.flatMap(route=>route.edges.map(edge=>edge.line)).flatMap(line=>line==='CCL'?['CCL','CEL']:[line]))];
 const feeds=await Promise.all(lines.flatMap(line=>['crowding','crowding-forecast'].map(async endpoint=>{try{const response=await fetch(`/api/lta/${endpoint}?line=${encodeURIComponent(line)}`,{signal:AbortSignal.timeout(10000),cache:'no-store'});return response.ok?response.json():{source:'unavailable',line};}catch{return {source:'unavailable',line};}})));
 if(request!==crowdRequest)return;
 const official=annotateCrowding(basePlan,feeds,places,nextDeparture(state.departure),boardingCrowd);
 render(false,official,true);
}
function activateCheckedJourney(next,meta){checkedMode=meta;plan=applyAccessLegs(next,{...accessLegs,originStationName:places[state.origin].name,destinationLabel:addresses.destination?.label||places[state.destination].name});selected=plan.best.id;render(false,plan);showMap(true);toast('Checked route applied to your map and journey steps.');}
function stepHtml(s,i){return `<div class="step-row"><span class="step-number">${i+1}</span><div><strong>${s.title}</strong><p>${s.detail}</p></div><span>${s.minutes} min</span></div>`;}
let mapBounds={minLon:103.82,maxLon:103.96,minLat:1.26,maxLat:1.38},roadData=[];
const lineColors={NSL:'#cf4552',EWL:'#38845c',CGL:'#38845c',NEL:'#9354b8',CCL:'#c28a1f',DTL:'#3674cd',TEL:'#8b6550',BPL:'#74845b',SLRT:'#778758',PLRT:'#778758'};
function project([lon,lat]){return [65+(lon-mapBounds.minLon)/(mapBounds.maxLon-mapBounds.minLon)*770,65+(mapBounds.maxLat-lat)/(mapBounds.maxLat-mapBounds.minLat)*460];}
function path(points){return points.map((p,i)=>`${i?'L':'M'}${project(p).map(v=>v.toFixed(1)).join(',')}`).join(' ');}
function drawMap(){if(!plan)return;const route=currentRoute(),original=plan.originalUsual||plan.usual,points=[...route.geometry,...original.geometry];let minLon=Math.min(...points.map(p=>p[0])),maxLon=Math.max(...points.map(p=>p[0])),minLat=Math.min(...points.map(p=>p[1])),maxLat=Math.max(...points.map(p=>p[1]));const centerLon=(minLon+maxLon)/2,centerLat=(minLat+maxLat)/2,lonSpan=Math.max(.035,maxLon-minLon)*1.22,latSpan=Math.max(.025,maxLat-minLat)*1.25;mapBounds={minLon:centerLon-lonSpan/2,maxLon:centerLon+lonSpan/2,minLat:centerLat-latSpan/2,maxLat:centerLat+latSpan/2};
 $('#geography').innerHTML=roadData.map(e=>`<path d="${path(e.geometry.map(p=>[p.lon,p.lat]))}" fill="none" stroke="#dce4d7" stroke-width="1.5"/>`).join('')+network.edges.filter((_,i)=>i%2===0).map(e=>`<path d="${path([places[e.from].coord,places[e.to].coord])}" fill="none" stroke="${lineColors[e.line]}" stroke-width="1.5" opacity=".25"/>`).join('');
 let html=`<path d="${path(original.geometry)}" fill="none" stroke="#759982" stroke-width="5" stroke-dasharray="7 7"/>`;
 html+=`<path d="${path(route.geometry)}" fill="none" stroke="white" stroke-width="10" stroke-linejoin="round"/><path d="${path(route.geometry)}" fill="none" stroke="#4d7bd3" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/>`;
 const affectedEdges=plan.checkedAffectedEdges||((plan.event.delay)?affectedPairs.map(([a,b])=>({from:a,to:b})):[]);for(const edge of affectedEdges)html+=`<path d="${path([places[edge.from].coord,places[edge.to].coord])}" fill="none" stroke="#c9715a" stroke-width="7" stroke-dasharray="5 3"/>`;
 const important=new Set([state.origin,state.destination,...route.edges.filter((e,i)=>i&&e.line!==route.edges[i-1].line).map(e=>e.from)]);let labels='';for(const id of route.stationIds){const[x,y]=project(places[id].coord);html+=`<circle cx="${x}" cy="${y}" r="${important.has(id)?8:4}" fill="white" stroke="#4d7bd3" stroke-width="3"/>`;if(important.has(id)){const label=places[id].name,w=Math.max(80,label.length*8+18),lx=Math.max(w/2+4,Math.min(896-w/2,x));labels+=`<rect x="${lx-w/2}" y="${y-38}" width="${w}" height="25" rx="5" fill="white"/><text x="${lx}" y="${y-21}" text-anchor="middle" fill="#294b40" font-size="13" font-family="system-ui" font-weight="600">${escape(label)}</text>`;}}
 if(gpsFix){const[x,y]=project(gpsFix.coord);html+=`<circle cx="${x}" cy="${y}" r="10" fill="#173f35" stroke="white" stroke-width="3"/>`;labels+=`<text x="${x}" y="${y+27}" text-anchor="middle" font-size="13" fill="#173f35">GPS start</text>`;}
 $('#map-routes').innerHTML=html;$('#map-labels').innerHTML=labels;}
async function loadMap(){try{const response=await fetch('/data/osm-roads.json');if(!response.ok)throw Error();const data=await response.json();roadData=data.elements.filter(e=>e.geometry);drawMap();}catch{roadData=[];drawMap();}}
$('#journey-form').addEventListener('submit',e=>{e.preventDefault();checkedMode=null;state.origin=$('#origin').value;state.destination=$('#destination').value;state.deadline=$('#deadline').value;save();render();toast('Your routes have been rebalanced.');});
$('#route-list').addEventListener('click',e=>{const b=e.target.closest('[data-route]');if(b){selected=b.dataset.route;render(false);}});
$$('[data-view]').forEach(b=>b.addEventListener('click',()=>switchView(b.dataset.view)));
function switchView(view){for(const key of ['journey','week','settings'])$('#'+key+'-view').classList.toggle('hidden',key!==view);$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='week')renderWeek();if(view==='settings')fillForm();document.body.dataset.screen=view;window.scrollTo({top:0,behavior:'instant'});}
$('#close-modal').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
$('#scenario-open').onclick=()=>{showModal('Every morning is different.',Object.entries(scenarios).map(([key,s],i)=>`<button class="scenario-option" data-scenario="${key}"><span>${['↯','☀','◷','☂','▦'][i]}</span><div><strong>${s.name}</strong><p>${s.description}</p></div></button>`).join(''),'TRY A MORNING · SYNTHETIC REPLAYS');};
$('#modal-content').addEventListener('click',e=>{const b=e.target.closest('[data-scenario]');if(b){checkedMode=null;state.scenario=b.dataset.scenario;save();render();switchView('journey');modal.close();toast(`${scenarios[state.scenario].name} replay loaded`);}if(e.target.closest('#next-step')){stepIndex++;showJourney();}if(e.target.closest('#end-trip')){try{localStorage.removeItem('margin-active-trip');}catch{}modal.close();toast('Journey complete. You’ve got this.');}if(e.target.closest('#refresh-weather'))refreshWeather();});
$('#why-button').onclick=()=>{const r=plan.best;showModal('A little buffer changes everything.',`<p>We rank the available journeys using the slower end of their estimated arrival range, then account for crowding and your preferences.</p><div class="explanation-row"><span>Your arrival deadline</span><strong>${state.deadline}</strong></div><div class="explanation-row"><span>Usual route, cautious arrival</span><strong>${formatTime(plan.usual.arrival)}</strong></div><div class="explanation-row"><span>Recommended, cautious arrival</span><strong>${formatTime(r.arrival)}</strong></div><div class="explanation-row"><span>Your remaining buffer</span><strong>${r.buffer} minutes</strong></div><p>${plan.notice} Alerts trigger below your ${state.threshold}-minute buffer threshold. We keep your usual route when it is safe and within five minutes of the best option.</p><span class="source-label">RULE-BASED ESTIMATE · NOT A PROBABILITY</span>`);};
$('#quiet-settings').onclick=()=>switchView('settings');
$('#settings-form').onsubmit=e=>{e.preventDefault();checkedMode=null;state.departure=$('#departure').value;state.threshold=Number($('#threshold').value);state.comfort=$('#comfort').checked;state.priority=$('#priority').value;state.walkBreak=Number($('#walkBreak').value);state.large=$('#large-text').checked;const active=routines.find(item=>item.id===activeRoutineId);active.name=$('#routine-name').value.trim();active.enabled=$('#routine-enabled').checked;active.weekdays=$$('[data-weekday]:checked').map(box=>Number(box.dataset.weekday));if(!validWeekdays(active.weekdays)){toast('Choose at least one active weekday.');return;}save();fillForm();render();toast('Routine schedule saved on this device.');};
$('#routine-list').onclick=event=>{const button=event.target.closest('[data-routine-id]');if(!button)return;save();const routine=routines.find(item=>item.id===button.dataset.routineId);if(!routine)return;activeRoutineId=routine.id;state={...defaults,...routine.state};gpsFix=null;addresses={origin:null,destination:null};accessLegs={};checkedMode=null;save();fillForm();render();toast(`${routine.name} selected.`);};
$('#add-routine').onclick=()=>{save();const id=`routine-${Date.now()}`;routines.push({id,name:`Routine ${routines.length+1}`,enabled:true,weekdays:[1,2,3,4,5],state:{...state}});activeRoutineId=id;state={...state};save();fillForm();toast('New routine added. Edit its journey and schedule.');};
$('#delete-routine').onclick=()=>{if(routines.length===1)return;const index=routines.findIndex(item=>item.id===activeRoutineId);routines.splice(index,1);const next=routines[Math.max(0,index-1)];activeRoutineId=next.id;state={...defaults,...next.state};gpsFix=null;addresses={origin:null,destination:null};accessLegs={};checkedMode=null;save();fillForm();render();toast('Routine deleted.');};
$('#clear-data').onclick=()=>{try{localStorage.removeItem('margin-routine');localStorage.removeItem('margin-routines');localStorage.removeItem('margin-active-trip');}catch{}state={...defaults};activeRoutineId='routine-1';routines=[{id:activeRoutineId,name:'Work commute',enabled:true,weekdays:[1,2,3,4,5],state:{...state}}];gpsFix=null;addresses={origin:null,destination:null};accessLegs={};checkedMode=null;save();fillForm();render();toast('Your saved routines and trip have been cleared.');};
$('#network-info').onclick=()=>showModal('What changed on your route?',`<span class="source-label">${plan.event.label}</span><p>${plan.event.description}</p><p>${plan.event.delay?'The affected segment is Paya Lebar → Aljunied → Kallang. Only routes traversing this segment receive the replay penalty.':'No major incident is active in this replay.'}</p><p>Use Check official service alerts below your recommendation for a separate LTA check. Replay conditions never imply current free bus boarding or shuttle availability.</p>`);
$('#weather-info').onclick=()=>showModal('Check the sky before you go.',`<p>The journey currently uses <strong>${plan.event.rain?'rainy':'dry'} replay conditions</strong>. You can separately check the latest public forecast for Tampines.</p><button class="primary-button" id="refresh-weather">Fetch current NEA forecast ↗</button><div id="weather-result"></div>`,'WEATHER · SOURCE CHECK');
async function refreshWeather(){const b=$('#refresh-weather'),out=$('#weather-result');b.disabled=true;out.innerHTML='<p>Checking data.gov.sg…</p>';try{const r=await fetch('https://api-open.data.gov.sg/v2/real-time/api/two-hr-forecast',{signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error();const data=await r.json();const item=data.data?.items?.[0];const forecast=item?.forecasts?.find(x=>x.area==='Tampines');if(!forecast)throw Error();out.innerHTML=`<span class="source-label">LIVE FETCH · NEA VIA DATA.GOV.SG</span><p><strong>Tampines: ${escape(forecast.forecast)}</strong><br>Issued: ${escape(item.timestamp)}<br>Valid: ${escape(item.valid_period?.start)} to ${escape(item.valid_period?.end)}</p><p>Shown separately from the replay so current weather is never mixed silently with synthetic transport data.</p>`;}catch{out.innerHTML='<p>Current weather is unavailable. The labelled replay remains available; no live forecast has been assumed.</p>';}finally{b.disabled=false;}}
function renderWeek(){const tomorrow=new Date(Date.now()+86400000),weekday=tomorrow.getDay()||7,active=scheduledRoutines(routines,weekday);$('#week-content').innerHTML=`<article class="week-card"><span class="source-label">TOMORROW · SYNTHETIC PLANNED EVENT</span><h3>EWL frequency reduced, 07:00–09:00</h3><p>Preview how this work window would affect a scheduled routine. Unaffected routes receive no disruption penalty.</p>${active.length?active.map(item=>`<button class="primary-button" data-preview-routine="${escape(item.id)}">Check ${escape(item.name)} <span>↗</span></button>`).join(''):'<p>No enabled routine is scheduled for tomorrow.</p>'}</article><article class="week-card"><h3>Your day-before check</h3><p>${active.length} enabled routine${active.length===1?'':'s'} match tomorrow. Checks run when you open this view; background notifications are not enabled.</p></article>`;$$('[data-preview-routine]').forEach(button=>button.onclick=()=>{save();const routine=routines.find(item=>item.id===button.dataset.previewRoutine);activeRoutineId=routine.id;state={...defaults,...routine.state,scenario:'planned'};save();fillForm();render();switchView('journey');toast(`${routine.name} planned-works replay loaded.`);});}
$('#start-journey').onclick=()=>{stepIndex=0;try{if(!gpsFix)localStorage.setItem('margin-active-trip',JSON.stringify({route:currentRoute(),savedAt:new Date().toISOString(),scenario:state.scenario}));}catch{}showJourney();};
function showJourney(){const r=currentRoute();if(stepIndex>=r.steps.length){showModal('A little breathing room. You’re here.',`<p>You’ve reached ${places[state.destination].name}. This walkthrough used illustrative timings and manually advanced steps.</p><button class="primary-button" id="end-trip">Finish journey ✓</button>`,'JOURNEY WALKTHROUGH');return;}const s=r.steps[stepIndex];showModal(s.title,`<div class="journey-progress"><div style="width:${(stepIndex+1)/r.steps.length*100}%"></div></div><p>${s.detail}</p><div class="explanation-row"><span>Estimated leg duration</span><strong>${s.minutes} minutes</strong></div><div class="explanation-row"><span>Journey estimate</span><strong>${formatTime(plan.start+r.min)}–${formatTime(r.arrival)}</strong></div><p>${gpsFix?'GPS journey stays in memory for this session.':'Saved on this device for the journey.'} ${navigator.onLine?'Replay conditions, not live navigation.':'Offline: conditions may have changed.'}</p><button class="primary-button" id="next-step">${stepIndex===r.steps.length-1?'I’ve arrived':'Done · next step'} →</button>`,`STEP ${stepIndex+1} OF ${r.steps.length} · DEMO WALKTHROUGH`);}
$('#sources-button').onclick=()=>showModal('Clear about what we know.',`<p><strong>Network:</strong> ${Object.keys(places).length} stations across six MRT lines and three LRT networks, including the Changi Airport branch. Station coordinates come from LTA/URA open data via Wu Tingfeng’s station dataset. Topology follows LTA’s system map, checked ${metadata.checked}, including Circle Line 6.</p><p><strong>Route estimates:</strong> connected rail paths are computed locally. Travel times use distance-based assumptions, a 3-minute first-train wait and 5 minutes per transfer. Applicable LTA observations and forecasts are labelled on route cards; fallback crowding and route incidents remain labelled replays. Last-train times and LRT direction-specific schedules are not modelled.</p><p><strong>Walking:</strong> address search uses OneMap. Walking paths use OneMap when authorized and otherwise openrouteservice with OpenStreetMap data. Provider routes are checked for endpoint proximity, geometry, distance and duration, but do not prove step-free access, shelter or current pavement conditions. GPS-only station choices remain straight-line estimates.</p><p><strong>Privacy:</strong> GPS is requested only when you tap Use current location. Coordinates stay in memory for this page session, are not saved, and disappear on reload. Address coordinates are sent through the server only when you explicitly request walking directions.</p><p><strong>Map:</strong> OpenStreetMap road extract covers eastern/central Singapore. The island-wide rail overlay connects station coordinates schematically; it is not track geometry. Routes and map work offline once cached.</p><p><a href="https://github.com/elliotwutingfeng/singapore_train_station_coordinates" target="_blank" rel="noopener">Station dataset ↗</a> · <a href="https://openrouteservice.org/" target="_blank" rel="noopener">openrouteservice ↗</a> · <a href="https://data.gov.sg/open-data-licence" target="_blank" rel="noopener">Singapore Open Data Licence ↗</a> · <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OSM attribution ↗</a></p>`,'DATA & TRANSPARENCY');
function setZoom(value){zoom=Math.max(1,Math.min(2.5,value));const w=900/zoom,h=610/zoom;$('#route-map').setAttribute('viewBox',`${(900-w)/2} ${(610-h)/2} ${w} ${h}`);}$('#zoom-in').onclick=()=>setZoom(zoom+.25);$('#zoom-out').onclick=()=>setZoom(zoom-.25);$('#map-reset').onclick=()=>setZoom(1);
function connection(){$('#offline-banner').classList.toggle('hidden',navigator.onLine);}window.addEventListener('online',connection);window.addEventListener('offline',connection);
function renderMobileSummary(){const r=currentRoute();$('#origin-name').textContent=addresses.origin?.label||(gpsFix?`Current location → ${places[state.origin].name}`:places[state.origin].name);$('#destination-name').textContent=addresses.destination?.label||places[state.destination].name;$('#commute-summary').textContent=`${places[state.origin].station} → ${places[state.destination].station}`;$('#commute-time').textContent=`Leave ${state.departure} · arrive by ${state.deadline}`;$('#selected-arrival').textContent=`Arrive ${formatTime(r.arrival)}`;$('#selected-name').textContent=r.name;$('#start-journey').innerHTML=`${checkedMode?'Start checked journey':'Start replay journey'} <span aria-hidden="true">→</span>`;$('#mobile-start').innerHTML=`${checkedMode?'Start checked':'Start replay'} <span aria-hidden="true">→</span>`;}
function showMap(show){document.body.dataset.map=String(show);$('#show-plan').setAttribute('aria-pressed',String(!show));$('#show-map').setAttribute('aria-pressed',String(show));}
$('#show-plan').onclick=()=>showMap(false);$('#show-map').onclick=()=>showMap(true);$('#mobile-start').onclick=()=>$('#start-journey').click();
let installPrompt=null;window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;});
function chooseLocation(field){pickerField=field;gpsCandidate=null;gpsRequest++;showModal(field==='origin'?'Where are you starting?':'Where are you going?',`${field==='origin'?'<button type="button" id="use-gps" class="gps-button"><span aria-hidden="true">⌖</span><span><strong>Use current location</strong><small>Find nearby stations using GPS</small></span></button><div id="gps-status" role="status" aria-live="polite"></div>':''}<form id="address-search-form"><label for="address-search">Search a building, road or postal code</label><div class="address-search-row"><input id="address-search" type="search" minlength="2" maxlength="100" placeholder="e.g. One Raffles Place" required autocomplete="street-address"><button class="outline-button">Search address</button></div></form><div id="address-results" role="status" aria-live="polite"></div><div class="picker-divider">or choose a station</div><label for="station-search" class="picker-label">Search station or code</label><input id="station-search" type="search" placeholder="e.g. Woodlands, NE17, Orchard" autocomplete="off"><label for="line-filter" class="picker-label">Filter by line</label><select id="line-filter"><option value="">All MRT &amp; LRT lines</option>${Object.entries(lines).map(([id,name])=>`<option value="${id}">${id} · ${name}</option>`).join('')}</select><p id="station-count" class="picker-hint" aria-live="polite"></p><div class="location-options" id="station-results"></div>`,'SINGAPORE LOCATIONS');renderStationResults();$('#station-search').oninput=renderStationResults;$('#line-filter').onchange=renderStationResults;$('#address-search-form').onsubmit=searchAddress;if(field==='origin')$('#use-gps').onclick=requestGps;}
async function searchAddress(event){event.preventDefault();const out=$('#address-results'),button=event.submitter,query=$('#address-search').value.trim();button.disabled=true;out.textContent='Searching OneMap…';try{const response=await fetch(`/api/locations/search?q=${encodeURIComponent(query)}`,{signal:AbortSignal.timeout(10000),cache:'no-store'});const data=await response.json();if(!response.ok||data.source!=='onemap')throw Error(data.message||data.error||'Address search unavailable.');out.innerHTML=data.results.length?data.results.map((item,index)=>`<button type="button" class="location-option" data-address-index="${index}"><span><strong>${escape(item.label)}</strong><small>Verified by OneMap</small></span><span aria-hidden="true">→</span></button>`).join(''):'<p>No matching Singapore address found.</p>';out._results=data.results;}catch(error){out.textContent=error.message;}finally{button.disabled=false;}}
async function walkingRoute(start,end){const params=new URLSearchParams({startLon:start[0],startLat:start[1],endLon:end[0],endLat:end[1]});const response=await fetch(`/api/walking-route?${params}`,{signal:AbortSignal.timeout(15000),cache:'no-store'});const data=await response.json();if(!response.ok||!['onemap','openrouteservice'].includes(data.source))throw Error(data.message||data.error||'Walking route unavailable.');return data;}
function renderStationResults(){const query=$('#station-search').value.trim().toLowerCase(),line=$('#line-filter').value;const matches=Object.values(places).filter(p=>(!line||p.lines.includes(line))&&`${p.name} ${p.code} ${p.lines.map(l=>lines[l]).join(' ')}`.toLowerCase().includes(query)).sort((a,b)=>a.name.localeCompare(b.name));$('#station-count').textContent=`${matches.length} station${matches.length===1?'':'s'} · select to update your route`;$('#station-results').innerHTML=matches.length?matches.map(p=>`<button type="button" class="location-option" data-location="${p.id}" data-field="${pickerField}" aria-pressed="${state[pickerField]===p.id}"><span><strong>${escape(p.name)}</strong><small>${p.code} · ${p.lines.join(' / ')}</small></span><span aria-hidden="true">${state[pickerField]===p.id?'✓':'→'}</span></button>`).join(''):'<p>No matching station. Try another name or station code, or choose All lines.</p>';}
$('#choose-origin').onclick=()=>chooseLocation('origin');$('#choose-destination').onclick=()=>chooseLocation('destination');
$('#modal-content').addEventListener('click',async event=>{const option=event.target.closest('[data-location]');if(option){const field=option.dataset.field,key=option.dataset.location;if(!['origin','destination'].includes(field)||!Object.hasOwn(places,key))return;const next={...state,[field]:key};try{planJourney(next);if(field==='origin')gpsFix=null;addresses[field]=null;delete accessLegs[field];checkedMode=null;state=next;save();fillForm();render();modal.close();toast(`${field==='origin'?'Starting station':'Destination'} updated. Routes recalculated.`);}catch(error){toast(error.message);}}
 const addressButton=event.target.closest('[data-address-index]');if(addressButton){const out=$('#address-results'),item=out?._results?.[Number(addressButton.dataset.addressIndex)];if(!item)return;addressButton.disabled=true;out.setAttribute('aria-busy','true');try{const nearest=nearestStations(item.coord,places,1)[0],field=pickerField;const walk=field==='origin'?await walkingRoute(item.coord,nearest.coord):await walkingRoute(nearest.coord,item.coord);state={...state,[field]:nearest.id};addresses[field]=item;accessLegs[field]=walk;if(field==='origin')gpsFix=null;checkedMode=null;save();fillForm();render();modal.close();toast(`${field==='origin'?'Start':'Destination'} connected to ${nearest.name} by a verified walk.`);}catch(error){toast(error.message);}finally{out?.setAttribute('aria-busy','false');}}
 const nearby=event.target.closest('[data-gps-station]');if(nearby&&gpsCandidate){const key=nearby.dataset.gpsStation,next={...state,origin:key};try{planJourney({...next,originLocation:gpsCandidate});gpsFix={coord:gpsCandidate.coord,accuracy:gpsCandidate.accuracy,timestamp:gpsCandidate.timestamp};addresses.origin=null;delete accessLegs.origin;checkedMode=null;state=next;save();fillForm();render();modal.close();toast(`GPS start set via ${places[key].name}.`);}catch(error){toast(error.message);}}});
function requestGps(){const out=$('#gps-status'),button=$('#use-gps');if(!navigator.geolocation){out.textContent='GPS is unavailable in this browser. Search for a station below.';return;}if(!window.isSecureContext){out.textContent='Location requires HTTPS. Open the published Margin link on your phone.';return;}const request=++gpsRequest;button.disabled=true;out.textContent='Finding your location… Allow access when your browser asks.';navigator.geolocation.getCurrentPosition(position=>{if(request!==gpsRequest||!modal.open||!$('#gps-status'))return;button.disabled=false;try{gpsCandidate=validatePosition(position,places);out.innerHTML=`<p>Location accuracy: about ${Math.round(gpsCandidate.accuracy)} m. Choose your boarding station. Walking estimates are approximate.</p>${gpsCandidate.nearby.filter(s=>s.distance<=3).map(s=>`<button class="location-option" type="button" data-gps-station="${s.id}"><span><strong>${escape(s.name)}</strong><small>${s.distance.toFixed(2)} km away · about ${Math.max(2,Math.ceil(s.distance*1.3/.075))} min walk</small></span><span aria-hidden="true">→</span></button>`).join('')}`;}catch(error){out.textContent=error.message;}},error=>{if(request!==gpsRequest||!modal.open||!$('#gps-status'))return;button.disabled=false;out.textContent=gpsError(error);},{enableHighAccuracy:true,timeout:12000,maximumAge:60000});}
modal.addEventListener('close',()=>{gpsRequest++;gpsCandidate=null;});
$('#edit-arrival').onclick=()=>{showModal('When do you need to arrive?',`<form id="arrival-form"><label for="arrival-time">Arrive by</label><input id="arrival-time" type="time" value="${state.deadline}" required><button type="submit" class="primary-button">Update arrival time →</button></form>`,'YOUR ARRIVAL DEADLINE');$('#arrival-form').onsubmit=event=>{event.preventDefault();const next={...state,deadline:$('#arrival-time').value};planJourney(next);checkedMode=null;state=next;save();fillForm();render();modal.close();toast('Arrival time updated.');};};
$('#install-app').onclick=async()=>{if(installPrompt){await installPrompt.prompt();const result=await installPrompt.userChoice;installPrompt=null;if(result.outcome==='accepted')toast('Margin has been added to your home screen.');return;}showModal('Your commute, one tap away.','<p><strong>iPhone:</strong> open Margin in Safari, tap Share, then choose Add to Home Screen.</p><p><strong>Android:</strong> open Margin in Chrome, open the menu, then choose Install app or Add to Home screen.</p><p>Use the published HTTPS link on your phone. Margin opens as a standalone web app where your browser supports it.</p>','ADD TO HOME SCREEN');};
for(const field of ['origin','destination'])$('#'+field).innerHTML=Object.values(places).sort((a,b)=>a.name.localeCompare(b.name)).map(p=>`<option value="${p.id}">${escape(p.name)}</option>`).join('');fillForm();render();loadMap();connection();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'configure_commute_replay',title:'Configure commute replay',description:'Set a supported demo corridor and replay scenario, recompute routes, and save the routine on this device. Does not fetch live transport data.',inputSchema:{type:'object',properties:{origin:{type:'string',enum:Object.keys(places)},destination:{type:'string',enum:Object.keys(places)},scenario:{type:'string',enum:Object.keys(scenarios)}},required:['origin','destination','scenario'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).some(k=>!['origin','destination','scenario'].includes(k))||!Object.hasOwn(places,input.origin)||!Object.hasOwn(places,input.destination)||!Object.hasOwn(scenarios,input.scenario))throw new Error('Invalid supported corridor or replay scenario.');const next={...state,...input};planJourney(next);state=next;gpsFix=null;save();fillForm();render();switchView('journey');return {scenario:state.scenario,recommendedRoute:plan.best.id,arrival:formatTime(plan.best.arrival),bufferMinutes:plan.best.buffer,dataMode:'synthetic transport replay'};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}

function renderEveryday(){
 const r=currentRoute(),labels={balanced:'Protect my time',simple:'Fewer changes',active:'Make room to walk'};
 $('#everyday-content').innerHTML=`<div class="daily-heading"><div><span class="source-label">YOUR EVERYDAY ROUTINE</span><h3>${labels[state.priority]||labels.balanced}</h3></div><button id="daily-settings" class="text-button">Edit</button></div><div class="daily-metrics"><span><strong>${r.walk} min</strong> walking allowance</span><span><strong>${r.transfers}</strong> train changes</span></div><p>${state.priority==='active'?`Includes a ${state.walkBreak}-minute optional walking break before boarding. ${plan.event.rain?'Rain in this replay: consider reducing your break.':'Choose a familiar walking path.'}`:state.priority==='simple'?'Recommendations give each train change an extra preference penalty.':'Your arrival deadline comes first. Compare a different departure to find more breathing room.'}</p><button id="compare-departure" class="outline-button">Find my departure window ↗</button>`;
 $('#daily-settings').onclick=()=>switchView('settings');$('#compare-departure').onclick=showDepartureOptions;
}
function showDepartureOptions(){
 const start=Number(state.departure.slice(0,2))*60+Number(state.departure.slice(3)),rank={low:0,medium:1,high:2};
 const options=[-30,-15,0,15,30].filter(offset=>start+offset>=0&&start+offset<1440).map(offset=>{const departure=formatTime(start+offset),p=planJourney({...state,departure,originLocation:gpsFix});const r=p.best;return {departure,r,buffer:plan.due-(start+offset+r.max)};});
 showModal('A little flexibility goes a long way.',`<p>Compare departures around ${state.departure}. Your arrival deadline stays ${state.deadline}. Choose one to update your plan.</p><span class="source-label">DEMO CROWD MODEL · NOT LIVE OCCUPANCY</span><p>On ordinary days, this model assumes busier EWL, NSL and NEL trains at 07:30–09:00 and 17:00–19:00. Shifting travel could spread demand; this does not predict a seat.</p><div class="departure-options">${options.map(o=>`<button class="location-option" data-departure="${o.departure}" ${o.buffer<0?'disabled':''}><span><strong>${o.departure}${o.departure===state.departure?' · current':''}</strong><small>${o.r.min}–${o.r.max} min · ${['Lower','Moderate','Higher'][rank[o.r.crowd]]} modelled crowding</small><small>${o.buffer<0?`${-o.buffer} min after deadline`:`${o.buffer} min arrival buffer`}</small></span><span aria-hidden="true">${o.buffer<0?'—':'→'}</span></button>`).join('')}</div><p>Options missing your deadline cannot be selected. Estimates exclude operating hours; check actual service before travelling.</p>`,'YOUR DEPARTURE WINDOW');
}
$('#modal-content').addEventListener('click',event=>{const button=event.target.closest('[data-departure]');if(!button)return;checkedMode=null;state.departure=button.dataset.departure;save();fillForm();render();modal.close();toast('Departure updated. Your arrival deadline is unchanged.');});
